package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class YearSixRatioSplitTest {
 @Test public void ratioFactsHaveUniqueMultiplicationAndDivisionConditions(){Set<String> seen=new HashSet<>();boolean up=false,down=false;for(int i=0;i<3312;i++){Question q=RatioSplitSupply.at("proportion",i);assertTrue(seen.add(q.signature()));Matcher m=Pattern.compile("(\\d+) : (\\d+) = (\\d+) : x").matcher(q.prompt);assertTrue(m.find());int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2)),c=Integer.parseInt(m.group(3));up|=c>a;down|=c<a;Rational expected=Rational.of(b*c,a);assertTrue(new Checker().check(q,List.of(),List.of(expected.toString())).correct());q.answers=new String[]{"999"};q.expression="poison";HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(5,h.size());List<String> inputs=List.of(""+a,""+b,""+c,Rational.of(c,a).toString(),expected.toString());for(int j=0;j<5;j++)assertTrue(h.step(j).accepts(inputs.get(j)));}assertTrue(up&&down);}
 @Test public void unequalAllocationsUseSevenStudentFieldsAndNoComputedValuesInFrames(){Set<String> seen=new HashSet<>();for(int i=0;i<2640;i++){Question q=RatioSplitSupply.at("el_proportional_split",i);assertTrue(seen.add(q.signature()));Matcher m=Pattern.compile("전체 (\\d+)을 (\\d+):(\\d+)").matcher(q.prompt);assertTrue(m.find());int total=Integer.parseInt(m.group(1)),a=Integer.parseInt(m.group(2)),b=Integer.parseInt(m.group(3)),unit=total/(a+b);assertNotEquals(a,b);assertTrue(new Checker().check(q,List.of(),List.of(""+(a*unit),""+(b*unit))).correct());q.answers=new String[]{"999","999"};HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertFalse(h.canTransfer());List<String> values=List.of(""+total,""+a,""+b,""+(a+b),""+unit,""+(a*unit),""+(b*unit));for(int j=0;j<7;j++){assertTrue(h.step(j).accepts(values.get(j)));assertEquals("",h.step(j).after);assertFalse(h.step(j).before.matches(".*\\d.*"));}}Question legacy=new Question("el_proportional_split","전체 60을 2:3로 비례배분한 두 부분은?","","24","36");assertEquals(7,HelpPlan.forQuestion(legacy).size());}
 @Test public void selectedGradeAndFreshSupplyReuseTypes(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(98));for(String id:List.of("proportion","el_proportional_split")){assertTrue(pack.inGrade(id,6));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}}Question ordinary=g.next("el_proportional_split",List.of(),false,CurriculumLimits.NONE);assertEquals(7,ordinary.studyGuide.frames.size());assertFalse(ordinary.studyGuide.transfer);for(var frame:ordinary.studyGuide.frames)assertFalse(frame.before.matches(".*\\d.*"));}
}
